import numpy as np

def max_pool(F, s):
    n, h, w = F.shape
    return F.reshape(n, h // s, s, w // s, s).max(axis=(2, 4))

def avg_pool(F, s):
    n, h, w = F.shape
    return F.reshape(n, h // s, s, w // s, s).mean(axis=(2, 4))

