import numpy as np
from scipy import ndimage as ndi

def conv_layer(img, W, b):
    maps = np.stack([ndi.correlate(img, w, mode="nearest") + bb for w, bb in zip(W, b)])
    return np.maximum(maps, 0)

def pool2(maps):
    c, h, w = maps.shape
    return maps.reshape(c, h // 2, 2, w // 2, 2).max(axis=(2, 4))

