def iou(a, b):
    w = min(a[2], b[2]) - max(a[0], b[0])
    h = min(a[3], b[3]) - max(a[1], b[1])
    inter = max(0, w) * max(0, h)
    area = lambda r: (r[2] - r[0]) * (r[3] - r[1])
    return inter / (area(a) + area(b) - inter)

def match(dets, true, thr=0.5):
    """Сопоставление по убыванию уверенности → (tp, fp, fn)."""
    used, tp, fp = set(), 0, 0
    for box, conf in sorted(dets, key=lambda d: -d[1]):
        cand = [(iou(box, t), j) for j, t in enumerate(true) if j not in used]
        best_iou, best_j = max(cand) if cand else (0, None)
        if best_iou >= thr:
            tp += 1
            used.add(best_j)
        else:
            fp += 1
    return tp, fp, len(true) - tp

